package org.apache.commons.fileupload2.core;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;

import org.junit.jupiter.api.Test;

/**
 * Tests for {@link DeferrableOutputStream}.
 */
public class DeferrableOutputStreamTest1 {

    /**
     * Tests that the output stream immediately uses a file when the threshold is zero,
     * even when no data is written. This ensures that a persistent storage location
     * is established from the start, reports its state correctly, and that the
     * resulting file is empty.
     *
     * @throws IOException if an I/O error occurs during file operations.
     */
    @Test
    public void testImmediateFileCreationWithZeroThreshold() throws IOException {
        final File outputFile = Files.createTempFile("testImmediateFileCreation", ".dat").toFile();
        outputFile.deleteOnExit(); // Ensure cleanup.

        // Configure the output mechanism with a zero threshold for immediate file usage.
        try (final DeferrableOutputStream dos = new DeferrableOutputStream(0, outputFile)) {

            // Confirm the system reports it is not in-memory and has a storage location.
            // With a zero threshold, it should be configured for file output from the start.
            // Note: In this implementation, isInMemory() may depend on whether a write has occurred.
            // We are testing the configuration and post-closure state.

            // The test primarily focuses on the state after closing.
        } // try-with-resources calls close(), which should trigger empty file creation.

        // Re-open stream to check its post-closure state and content
        try (final DeferrableOutputStream dos = new DeferrableOutputStream(0, outputFile)) {
            // Verify again that the system reports file-based operation.
            assertFalse(dos.isInMemory(), "Should report not in-memory after close.");
            assertNotNull(dos.getStoreLocation(), "Storage location must be accessible after close.");
            assertTrue(outputFile.exists(), "Storage location should exist as a valid file after close.");
            assertTrue(outputFile.isFile(), "Storage location must be a regular file.");

            // Retrieve the content and confirm it's an empty data set.
            final byte[] content = dos.getData();
            assertNotNull(content, "Retrieved content should not be null.");
            assertArrayEquals(new byte[0], content, "Content should be empty as no data was written.");
        }
    }
}

package org.apache.commons.fileupload2.core;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Tests {@link MultipartInput}.
 */
public class MultipartInputTest {

    @Test
    public void testComprehensiveConfiguration() {
        // Prepare sample content data as a stream source.
        final String sampleData = "--myBoundary\\r\\nContent-Disposition: form-data; name=\\\"field1\\\"\\r\\n\\r\\nvalue1\\r\\n--myBoundary--";
        final byte[] sampleBytes = sampleData.getBytes(StandardCharsets.UTF_8);
        final InputStream dataStream = new ByteArrayInputStream(sampleBytes);
        final long contentLength = sampleBytes.length;

        // Convert a predefined boundary marker into its binary representation.
        final String boundaryString = "myBoundary";
        final byte[] boundary = boundaryString.getBytes(StandardCharsets.UTF_8);

        // Calculate the minimum buffer capacity.
        final int bufferSize = boundary.length + 4 + 1; // 4 bytes for \\r\\n--

        // Configure the multipart processing system.
        final MultipartInput.Builder builder = MultipartInput.builder()
                .setBoundary(boundary)
                .setBufferSize(bufferSize)
                .setProgressListener(null)
                .setContentLength(contentLength);

        // Construct the multipart processor.
        final MultipartInput multipartInput = builder.build(dataStream);

        // Verify that the initialization completed successfully.
        assertThat(multipartInput).isNotNull();
    }
}

package org.apache.commons.fileupload2.core;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.fail;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

/**
 * Tests {@link MultipartInput}.
 */
public class MultipartInputTest {

    @Test
    public void testMaxPartHeaderSize() throws IOException {
        final String boundary = "----1234";
        final String requestString =
            "--" + boundary + "\r\n" +
            "Content-Disposition: form-data; name=\"file1\"; filename=\"file1.txt\"\r\n" +
            "Content-Type: text/plain\r\n" +
            "\r\n" +
            "Hello\r\n" +
            "--" + boundary + "\r\n" +
            "Content-Disposition: form-data; name=\"file2\"; filename=\"file2.txt\"\r\n" +
            "Content-Type: text/plain\r\n" +
            "A-Very-Long-Header-Name-To-Exceed-The-Size-Limit-Of-100-Bytes: and-a-correspondingly-long-value-just-to-be-sure\r\n" +
            "\r\n" +
            "World\r\n" +
            "--" + boundary + "--\r\n";

        final byte[] requestBytes = requestString.getBytes(StandardCharsets.UTF_8);
        final ByteArrayInputStream inputStream = new ByteArrayInputStream(requestBytes);
        final byte[] boundaryBytes = boundary.getBytes(StandardCharsets.UTF_8);

        final MultipartInput multi = MultipartInput.builder()
                .setInputStream(inputStream)
                .setBoundary(boundaryBytes)
                .setMaxPartHeaderSize(100)
                .get();

        assertNotNull(multi, "MultipartInput instance should not be null");

        try {
            boolean nextPart = multi.skipPreamble();
            while (nextPart) {
                final String headers = multi.readHeaders();
                System.out.println("Header length: " + headers.length());
                System.out.println("Headers: " + headers);
                assertNotNull(headers, "Headers string should not be null");
                multi.readBodyData(null);
                nextPart = multi.readBoundary();
            }
            fail("Expected FileUploadSizeException was not thrown.");
        } catch (final FileUploadSizeException e) {
            assertEquals(100, e.getPermitted(), "The permitted size should be 100.");
        }
    }
}

package org.apache.commons.fileupload2.core;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.function.IntConsumer;
import org.junit.jupiter.api.Test;

/**
 * Tests the state transitions of a DiskFileItem as data is written across a configurable threshold.
 */
public class DiskFileItemStateTest {

    /**
     * Validates the state of a {@link DiskFileItem} by checking its memory residency,
     * file persistence, size, and content.
     *
     * @param item The item to validate.
     * @param expectInMemory Whether the item is expected to be in memory.
     * @param expectPersisted Whether the item is expected to be persisted to disk.
     * @param expectedParentDir The directory where the persisted file should be located.
     * @param expectedSize The expected size of the item's data in bytes.
     * @param expectedContent The expected string content of the item.
     * @throws IOException if an I/O error occurs during validation.
     */
    private void validateState(
            final DiskFileItem item,
            final boolean expectInMemory,
            final boolean expectPersisted,
            final Path expectedParentDir,
            final Long expectedSize,
            final String expectedContent) throws IOException {

        assertEquals(expectInMemory, item.isInMemory(), "Mismatch on in-memory state.");

        if (expectPersisted) {
            final Path storeLocation = item.getStoreLocation();
            assertNotNull(storeLocation, "Expected a persisted file location, but it was null.");
            assertTrue(Files.exists(storeLocation), "Expected persisted file to exist, but it doesn't.");
            assertEquals(expectedParentDir, storeLocation.getParent(), "Persisted file is in the wrong directory.");
        } else {
            assertNull(item.getStoreLocation(), "Expected no persisted file location, but it was not null.");
        }

        if (expectedSize != null) {
            assertEquals(expectedSize.longValue(), item.getSize(), "Item size mismatch.");
        }

        if (expectedContent != null) {
            assertEquals(expectedContent, item.getString(StandardCharsets.UTF_8), "Item content mismatch.");
        }
    }

    @Test
    public void testStateTransitionAcrossThreshold() {
        final IntConsumer testLogic = threshold -> {
            final Path testDir = Path.of("target", DiskFileItemStateTest.class.getSimpleName());
            Path tempDir = null;
            try {
                Files.createDirectories(testDir);
                tempDir = Files.createTempDirectory(testDir, "test-sub-dir-");

                final var factory = DiskFileItemFactory.builder()
                        .setPath(tempDir)
                        .setThreshold(threshold)
                        .setCharset(StandardCharsets.UTF_8)
                        .build();

                assertEquals(threshold, factory.getThreshold(), "Factory threshold should match input.");

                final var item = (DiskFileItem) factory.createItem("field", "text/plain", true, "test.txt");
                assertEquals(threshold, item.getThreshold(), "Item threshold should match factory's.");

                // Initially, item should be in memory, empty, with no file.
                validateState(item, true, false, tempDir, 0L, "");

                final StringBuilder writtenContent = new StringBuilder();
                try (final OutputStream os = item.getOutputStream()) {
                    // Write bytes up to one less than the threshold.
                    for (int i = 0; i < threshold - 1; i++) {
                        final char c = (char) ('a' + (i % 26));
                        os.write(c);
                        writtenContent.append(c);
                        // Item should remain in memory.
                        validateState(item, true, false, tempDir, (long) (i + 1), null);
                    }

                    // Write the final byte to reach the threshold.
                    final char lastChar = (char) ('a' + ((threshold - 1) % 26));
                    os.write(lastChar);
                    writtenContent.append(lastChar);

                    // Item should now be persisted to disk.
                    validateState(item, false, true, tempDir, (long) threshold, null);
                }

                // After closing the stream, the item should remain persisted and its content should be available.
                validateState(item, false, true, tempDir, (long) threshold, writtenContent.toString());

            } catch (final IOException e) {
                throw new UncheckedIOException(e);
            }
        };

        // Verify behavior with both a small and a large (greater than default buffer) threshold.
        testLogic.accept(5);
        testLogic.accept(8193);
    }
}
